#!/usr/bin/env python3
"""Regenerate the tracked local HTML from maintained STATUS.json."""
from pathlib import Path
from datetime import datetime
from zoneinfo import ZoneInfo
import html,json
root=Path(__file__).resolve().parent.parent
data=json.loads((root/'STATUS.json').read_text())
e=html.escape
cards=[]
for row in data['areas']:
 cards.append('<article data-status="'+e(row['status'])+'"><div class="line"><small>'+e(row['group'])+'</small><span class="badge '+e(row['status'])+'">'+e(row['label'])+'</span></div><h2>'+e(row['title'])+'</h2><p>'+e(row['finding'])+'</p><details><summary>검증·다음 단계</summary><p>'+e(row['next'])+'</p></details><a href="'+e(row['path'])+'">절차와 기록 ↗</a></article>')
page='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Surface · 상태와 재현</title><style>
*{box-sizing:border-box}body{margin:0;background:#eff3f9;color:#182b45;font:15px system-ui,sans-serif}main{max-width:1140px;margin:auto;padding:36px 24px}header{background:linear-gradient(120deg,#123356,#3f5c96);border-radius:24px;padding:36px;color:white}header p{color:#d9e5fb}h1{font-size:34px;margin:12px 0}small{letter-spacing:.07em;font-size:11px}p{line-height:1.8;color:#53657c;font-size:14px}.metrics{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}.metric{background:white;border-radius:14px;padding:18px 24px;flex:1;min-width:150px}.metric strong{display:block;font-size:22px}.metric span{font-size:12px;color:#697e98}nav{display:flex;gap:8px;flex-wrap:wrap;margin:22px 0}button{border:1px solid #cbd5e5;border-radius:50px;padding:9px 16px;background:white;color:#365574;cursor:pointer}button.active{background:#234f86;color:white}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}article{background:white;border:1px solid #dae3ef;border-radius:18px;padding:24px}article[hidden]{display:none}.line{display:flex;justify-content:space-between;align-items:center;gap:8px}.badge{font-size:11px;padding:5px 9px;border-radius:8px}.ok{background:#e0f4e8;color:#176744}.pending{background:#fff0d1;color:#8c611c}.open{background:#fbe1e6;color:#ab3451}.held{background:#e9edf3;color:#5b6d83}h2{font-size:20px;margin:13px 0}summary{cursor:pointer;color:#315e94;font-size:13px}a{display:inline-block;margin-top:15px;color:#315e94;text-decoration:none;font-size:13px}footer{background:#e0e8f3;border-radius:18px;padding:24px;margin-top:24px}code{font-family:monospace;background:#d4dfed;padding:3px 5px;border-radius:5px}footer p{margin:9px 0}@media(max-width:760px){.grid{grid-template-columns:1fr}main{padding:18px 12px}header{padding:25px}h1{font-size:27px}}@media print{nav{display:none}article{break-inside:avoid}.grid{display:block}article{margin:12px 0}}
</style><main><header><small>SURFACE / SYSTEM REVIEW</small><h1>현재 상태와 재현 가능한 설정</h1><p>Surface Laptop 7 13.8″ · Snapdragon X Plus · Debian 13 ARM64<br>설치·서명·실기기 동작의 검증 범위를 구분한 기록입니다.</p><small>UPDATED · NOW</small></header><section class="metrics"><div class="metric"><strong>PROGRESS%</strong><span>이번 점검·설정 진행률</span></div><div class="metric"><strong>Secure Boot ON</strong><span>현재 부팅 확인</span></div><div class="metric"><strong>5 components</strong><span>SH · Python 진입점</span></div><div class="metric"><strong>Offline</strong><span>대용량 파일은 로컬 별도 보관</span></div></section><nav><button class="active" data-filter="all">전체</button><button data-filter="ok">검증됨</button><button data-filter="pending">검증 대기</button><button data-filter="open">미해결</button><button data-filter="held">보류</button><button onclick="location.reload()">새로고침</button></nav><section class="grid">CARDS</section>BATTERY_DETAILS<section style="background:#06080b;border-radius:18px;padding:30px;text-align:center;margin-top:22px"><img src="desktop/files/boot-art/debian-logo.svg" width="300" alt="Debian 소용돌이 로고"><p style="color:#aab2bf">부팅·로그인용 로고 원본 · 버전 글자 없음</p></section><footer><strong>설치와 기록</strong><p><code>python3 setup.py --plan</code>으로 실행 범위를 확인하고 <code>bash setup.sh</code>로 전체 설치합니다. <code>python3 setup.py --component desktop</code>처럼 선택할 수도 있습니다. 각 디렉토리의 setup.sh와 setup.py는 같은 구현을 사용합니다.</p><p>Console의 Caddy·Kopia·code-server·계정은 별도 repository에서 관리합니다. 최초 MOK 등록, 펌웨어 설정, 재부팅과 로그인은 수동입니다. 미해결 하드웨어 동작과 Steam 전체 런타임·개인 데이터 복원까지 자동화됐다는 뜻은 아닙니다.</p><p><a href="README.md">설치 절차</a> · <a href="PORTABILITY.md">다른 Debian에 적용하는 범위</a> · <a href="SOURCES.md">출처와 패치</a> · <a href="NEXT.md">이어갈 작업</a></p><p>HTML도 Git에 저장하고 작업마다 갱신합니다. scripts/docs/configuration만 Git에 저장하며, 실제 오프라인 복구에는 무시된 바이너리 파일도 함께 복사해야 합니다.</p></footer></main><script>for(const b of document.querySelectorAll('[data-filter]'))b.addEventListener('click',()=>{for(const x of document.querySelectorAll('[data-filter]'))x.classList.remove('active');b.classList.add('active');for(const c of document.querySelectorAll('article'))c.hidden=b.dataset.filter!=='all'&&c.dataset.status!==b.dataset.filter});</script></html>'''
battery=json.loads((root/'drivers/files/power/battery-measurement.json').read_text())
last=next(x for x in reversed(battery['sleep_intervals']) if x.get('eligible'))
mean=battery['awake_weighted_mean_w']
comparison=f"""<section style="background:white;border-radius:18px;padding:24px;margin-top:22px"><h2>배터리 · 측정값과 Windows 참고 기준</h2><div style="overflow:auto"><table style="width:100%;border-collapse:collapse;text-align:left"><thead><tr><th>구간</th><th>측정·기준</th><th>해석</th></tr></thead><tbody><tr><td>최근 deep 절전</td><td>{last['hours']:.2f}h · 73→67% · {last['estimated_wh']:.2f}Wh</td><td>{last['mean_w']:.2f}W / {last['percentage_points_per_hour']:.2f}%p/h</td></tr><tr><td>깨어 있는 방전 표본</td><td>{battery['awake_sampled_hours']:.2f}h · 평균 {mean:.2f}W</td><td>현재 완충 용량으로 단순 환산 {battery['full_wh']/mean:.1f}h</td></tr><tr><td>배터리 건강도</td><td>{battery['full_wh']:.2f}/{battery['design_wh']:.2f}Wh</td><td>{battery['health_percent']:.1f}% · 연료 게이지 보고값</td></tr><tr><td>Windows Modern Standby 권장</td><td>16h 동안 5% 미만</td><td>현재 Linux 소비율은 이 권장치의 약 {last['percentage_points_per_hour']/0.3125:.1f}배</td></tr><tr><td>같은 모델 MS 공식 사용시간</td><td>웹 최대 13h / 로컬 영상 최대 20h</td><td>현재 혼합 작업과 직접 비교 불가</td></tr></tbody></table></div><p>아래 소비량은 이전 부팅·이번 최적화 전 기준값입니다. Windows에서 이 기기를 실측한 자료는 없습니다. 절전 중 소비는 잔량의 약 1%p 단위 측정과 전환 시점 오차를 포함합니다. 작업 평균은 충전·절전·120초 초과 표본 간격을 제외한 시간 가중값입니다. 현재 혼합 작업은 Firefox·Steam/FEX·Waydroid·개발 작업을 포함하며, 통제된 웹/영상 시험이 아닙니다.</p><p><a href="https://learn.microsoft.com/en-us/surface/tech-specs/surface-laptop-snapdragon-tech-specs">Microsoft 모델 사양</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/test/hlk/testref/36463e42-7d6e-408e-933f-dbf56ea41e65">대기 소비 권장치</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/design/device-experiences/modern-standby-sleepstudy">SleepStudy 기준</a> · <a href="drivers/files/power/README.md">측정 방법과 한계</a></p></section>"""
page=page.replace('BATTERY_DETAILS',comparison)
page=page.replace('NOW',datetime.now(ZoneInfo('Asia/Seoul')).strftime('%Y-%m-%d %H:%M KST')).replace('PROGRESS',str(data['progress'])).replace('CARDS',''.join(cards))
(root/'hardware-report.html').write_text(page)
print(root/'hardware-report.html')
